  `cd_msgs` int NOT NULL,
  `msg_line` int NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `comments` text,
  PRIMARY KEY (`id`),
  KEY `idx_exchange_ip` (`exchange_ip`),
